17	+  describe('canvas and svg export parity', () => {
18	+    type ParsedTspan = {
19	+      x: number;
20	+      y: number;
21	+      dy: number;
22	+      dx: number;
23	+      rotate: number;
24	+      baselineShift: number;
25	+      style: string;
26	+      text: string;
27	+    };
28	+
29	+    const numberFrom = (source: string, re: RegExp) => {
30	+      const match = source.match(re);
31	+      return match ? parseFloat(match[1]) : 0;
32	+    };
33	+
34	+    /**
35	+     * Pull every tspan out of an exported SVG string, keeping the geometry
36	+     * attributes, the raw style attribute and the inner text.
37	+     */
38	+    const parseTspans = (svg: string): ParsedTspan[] => {
39	+      const tspans: ParsedTspan[] = [];
40	+      const tspanRe = /<tspan\b([^>]*)>([\s\S]*?)<\/tspan>/g;
41	+      let match: RegExpExecArray | null;
42	+      while ((match = tspanRe.exec(svg)) !== null) {
43	+        const attributes = match[1];
44	+        const styleMatch = attributes.match(/style="([^"]*)"/);
45	+        const style = styleMatch ? styleMatch[1] : '';
46	+        const geometry = attributes.replace(/style="[^"]*"/, '');
47	+        tspans.push({
48	+          x: numberFrom(geometry, /\bx="(-?[\d.]+)"/),
49	+          y: numberFrom(geometry, /\by="(-?[\d.]+)"/),
50	+          dy: numberFrom(geometry, /\bdy="(-?[\d.]+)"/),
51	+          dx: numberFrom(geometry, /\bdx="(-?[\d.]+)"/),
52	+          rotate: numberFrom(geometry, /\brotate="(-?[\d.]+)"/),
53	+          baselineShift: numberFrom(style, /baseline-shift:\s*(-?[\d.]+)/),
54	+          style,
55	+          text: match[2],
56	+        });
57	+      }
58	+      return tspans;
59	+    };
60	+
61	+    /**
62	+     * Net downward displacement of a tspan relative to the line it sits on.
63	+     * Whichever single mechanism the implementation keeps, the visible result
64	+     * is the same number, so tests can compare this instead of an attribute.
65	+     */
66	+    const effectiveDrop = (tspan: ParsedTspan) =>
67	+      tspan.y + tspan.dy - tspan.baselineShift;
68	+
69	+    const tspanWithText = (tspans: ParsedTspan[], text: string) => {
70	+      const found = tspans.find((tspan) => tspan.text === text);
71	+      expect(found).toBeDefined();
72	+      return found!;
73	+    };
74	+
75	+    const TOLERANCE = 1e-6;
76	+
77	+    it('a raised character is displaced by its own offset and not by twice it', () => {
78	+      const deltaY = -14;
79	+      const text = new FabricText('abc', { styles: { 0: { 1: { deltaY } } } });
80	+      const tspans = parseTspans(text.toSVG());
81	+      const raised = tspanWithText(tspans, 'b');
82	+      const reference = tspanWithText(tspans, 'a');
83	+
84	+      expect(raised.y).toBe(reference.y);
85	+      expect(
86	+        Math.abs(effectiveDrop(raised) - effectiveDrop(reference) - deltaY),
87	+      ).toBeLessThan(TOLERANCE);
88	+    });
89	+
90	+    it('a lowered character is displaced by its own offset and not by twice it', () => {
91	+      const deltaY = 11;
92	+      const text = new FabricText('abc', { styles: { 0: { 1: { deltaY } } } });
93	+      const tspans = parseTspans(text.toSVG());
94	+      const lowered = tspanWithText(tspans, 'b');
95	+      const reference = tspanWithText(tspans, 'a');
96	+
97	+      expect(lowered.y).toBe(reference.y);
98	+      expect(
99	+        Math.abs(effectiveDrop(lowered) - effectiveDrop(reference) - deltaY),
100	+      ).toBeLessThan(TOLERANCE);
101	+    });
102	+
103	+    it('characters raised and lowered on the same line each keep their own displacement', () => {
104	+      const raisedBy = -14;
105	+      const loweredBy = 11;
106	+      const text = new FabricText('abcde', {
107	+        styles: { 0: { 1: { deltaY: raisedBy }, 3: { deltaY: loweredBy } } },
108	+      });
109	+      const tspans = parseTspans(text.toSVG());
110	+      const reference = tspanWithText(tspans, 'a');
111	+      const raised = tspanWithText(tspans, 'b');
